  const ix = Math.min(G.W - 1, Math.floor(fx)), iy = Math.min(G.H - 1, Math.floor(fy)), tx = fx - ix, ty = fy - iy;
  const r = (a, b) => G.rad[b * (G.W + 1) + a];
